"""Rasa A2A ``DefaultRequestHandler`` with ``messageId`` idempotency.

The a2a-sdk ``DefaultRequestHandler`` routes ``message/send`` and
``message/stream`` into ``AgentExecutor.execute()`` but does not replay prior
outcomes when the client retries with the same ``messageId``. This module
subclasses it so Rasa can:

1. **Cache hit** — return a stored terminal ``Task`` for duplicate
   ``(context_id, message_id)`` without calling ``handle_message()`` again.
2. **In flight** — reject a concurrent duplicate with
   :class:`~rasa.core.a2a_server.errors.A2AMessageInFlightConflict` (HTTP 409
   from :mod:`rasa.core.a2a_server.sanic_app`) until V2 persists a cacheable
   task (not merely until this handler returns). An error raised by the SDK
   call itself also ends in-flight for the key.
3. **Record** — persist terminal outcomes in
   :class:`~rasa.core.a2a_server.a2a_message_cache.A2AMessageCache` when V2
   saves a cacheable task (including background ``return_immediately`` turns).
4. **Context cap** — reject a send that would open a context over
   ``max_contexts`` with a stored ``FAILED`` task, before the SDK starts a
   producer for it.

A send without a ``contextId`` gets one derived from the caller and
``messageId``, so a retry of the same message resolves to the same dedup key.
Push callback URLs are screened by the ``push_url_validator`` the executor
passes in, before any push config is registered.

Dedup runs in :meth:`RasaA2ARequestHandler.prepare_message_dispatch` **before**
the SDK's ``_setup_active_task``, so terminal-task retries with the same
``taskId`` are handled here rather than as ``InvalidParamsError`` inside the SDK.

For streaming, :meth:`build_message_send_stream` performs the same checks
awaitably so Sanic can return 409 before SSE headers are sent.
"""

from __future__ import annotations

import uuid
from collections.abc import AsyncGenerator
from typing import TYPE_CHECKING, Any, Literal, NoReturn, cast

import structlog
from a2a.helpers import new_text_message
from a2a.server.context import ServerCallContext
from a2a.server.request_handlers import DefaultRequestHandler
from a2a.server.tasks import PushNotificationSender
from a2a.types import (
    AgentCard,
    CancelTaskRequest,
    InvalidParamsError,
    Message,
    Role,
    SendMessageRequest,
    Task,
    TaskState,
    TaskStatus,
    TaskStatusUpdateEvent,
)
from a2a.utils.errors import PushNotificationNotSupportedError
from a2a.utils.task import apply_history_length, validate_history_length

from rasa.core.a2a_server.a2a_message_cache import (
    IN_FLIGHT_LEASE_STATE_KEY,
    A2AMessageCache,
    CacheKey,
    cache_key_from_dispatch,
    caller_scope,
    in_flight_lease_from_call_context,
    replay_cached_stream,
    task_for_replay_from_params,
)
from rasa.core.a2a_server.context_guard import (
    CONTEXT_LIMIT_EXCEEDED_ERROR,
    A2AContextGuard,
)
from rasa.core.a2a_server.errors import (
    A2AMessageInFlightConflict,
    A2APushNotificationUrlRejected,
)

if TYPE_CHECKING:
    from a2a.server.agent_execution import AgentExecutor, RequestContext
    from a2a.server.agent_execution.active_task import ActiveTask
    from a2a.server.events import Event
    from a2a.server.tasks import PushNotificationEvent, TaskStore

structlogger = structlog.get_logger()

_TERMINAL_TASK_STATES = frozenset(
    {
        TaskState.TASK_STATE_COMPLETED,
        TaskState.TASK_STATE_CANCELED,
        TaskState.TASK_STATE_FAILED,
        TaskState.TASK_STATE_REJECTED,
    }
)

# ``ServerCallContext.state`` key: ``True`` when the caller chose a streaming
# method (``message/stream`` / ``SendStreamingMessage``), ``False`` for a
# non-streaming method (``message/send`` / ``SendMessage``). The method is the
# caller's only signal for whether it wants token streaming, push
# notifications included.
STREAMING_CALLER_STATE_KEY = "rasa_a2a_streaming_caller"

# Upper bound on task ids remembered by ``_TerminalPushLedger``. Entries only
# exist for tasks that already reached a terminal state, so the cap just keeps
# a long-running server from growing without bound.
_MAX_TERMINAL_PUSH_LEDGER_SIZE = 10_000


def _call_context(context: ServerCallContext | None) -> ServerCallContext:
    """SDK handlers require a call context; tests sometimes omit it."""
    return context if context is not None else ServerCallContext()


def _raise_push_url_policy_error(exc: A2APushNotificationUrlRejected) -> NoReturn:
    raise InvalidParamsError(message=exc.message) from exc


def _event_task_state(event: PushNotificationEvent) -> TaskState | None:
    if isinstance(event, Task):
        return event.status.state
    if isinstance(event, TaskStatusUpdateEvent):
        return event.status.state
    return None


class _TerminalPushLedger(PushNotificationSender):
    """Push sender that remembers which tasks already got a terminal push.

    The SDK's ``ActiveTask`` consumer and :meth:`RasaA2ARequestHandler.on_cancel_task`
    share this sender, so the handler can tell whether the SDK already
    delivered the terminal ``canceled`` event before it POSTs one itself.
    A task id is recorded as soon as a terminal event is handed to the inner
    sender, not after delivery: the SDK consumer may still be awaiting its
    POST when ``on_cancel_task`` resumes.
    """

    def __init__(self, inner: PushNotificationSender) -> None:
        self._inner = inner
        self._terminal_pushed: dict[str, None] = {}

    @property
    def inner(self) -> PushNotificationSender:
        """The wrapped sender that performs the actual POST."""
        return self._inner

    def has_terminal_push(self, task_id: str) -> bool:
        """Whether a terminal-state event for ``task_id`` was already sent."""
        return task_id in self._terminal_pushed

    async def send_notification(
        self, task_id: str, event: PushNotificationEvent
    ) -> None:
        """Record terminal events for ``task_id`` and delegate the POST."""
        if _event_task_state(event) in _TERMINAL_TASK_STATES:
            self._record_terminal_push(task_id)
        await self._inner.send_notification(task_id, event)

    def _record_terminal_push(self, task_id: str) -> None:
        self._terminal_pushed.pop(task_id, None)
        while len(self._terminal_pushed) >= _MAX_TERMINAL_PUSH_LEDGER_SIZE:
            oldest = next(iter(self._terminal_pushed))
            self._terminal_pushed.pop(oldest, None)
        self._terminal_pushed[task_id] = None


def _context_id_for_new_conversation(owner: str, message: Message) -> str | None:
    """Derive a stable ``context_id`` for a message that names no context or task.

    A generated one would differ per attempt, so a retry of the same
    ``message_id`` could never match the first attempt's dedup key.
    """
    if message.context_id or message.task_id or not message.message_id:
        return None
    return str(uuid.uuid5(uuid.uuid5(uuid.NAMESPACE_URL, owner), message.message_id))


async def _single_task_stream(task: Task) -> AsyncGenerator[Event, None]:
    yield task


def _opens_turn_for(event: object, message_id: str) -> bool:
    return isinstance(event, Task) and any(
        message.message_id == message_id for message in event.history
    )


class _RequestScopedActiveTask:
    """``ActiveTask`` view whose subscription starts at this request's own turn.

    Every request on a task subscribes to the same event stream. A request
    queued behind a running one would otherwise see the running request's
    events first and V2 would answer it with that request's result. The
    executor opens each turn with a ``Task`` whose history holds the request's
    user message, so events before that marker belong to an earlier request.
    """

    def __init__(self, active_task: ActiveTask, message_id: str) -> None:
        self._active_task = active_task
        self._message_id = message_id

    def __getattr__(self, name: str) -> Any:
        return getattr(self._active_task, name)

    async def subscribe(self, **kwargs: Any) -> AsyncGenerator[Event, None]:
        inner = self._active_task.subscribe(**kwargs)
        own_turn_started = False
        try:
            async for event in inner:
                if not own_turn_started:
                    if not _opens_turn_for(event, self._message_id):
                        continue
                    own_turn_started = True
                yield event
        finally:
            await inner.aclose()


class RasaA2ARequestHandler(DefaultRequestHandler):
    """SDK request handler wired to ``A2AMessageCache``.

    Built by ``RasaA2AAgentExecutor`` and passed to ``JSONRPCHandler`` as
    ``request_handler``.
    """

    def __init__(
        self,
        agent_executor: AgentExecutor,
        task_store: TaskStore,
        agent_card: AgentCard,
        message_cache: A2AMessageCache,
        context_guard: A2AContextGuard | None = None,
        push_sender: PushNotificationSender | None = None,
        **kwargs: object,
    ) -> None:
        """Initialize the SDK handler with executor, task store, and message cache.

        ``context_guard`` lets the handler reject a send for a new context over
        ``max_contexts`` before the SDK starts a producer for it.

        ``push_sender`` is wrapped in :class:`_TerminalPushLedger` so
        :meth:`on_cancel_task` can skip its fallback POST when the SDK already
        pushed the terminal event.
        """
        self._push_ledger: _TerminalPushLedger | None = (
            _TerminalPushLedger(push_sender) if push_sender is not None else None
        )
        super().__init__(
            agent_executor,
            task_store,
            agent_card,
            push_sender=self._push_ledger,
            **kwargs,
        )
        self._message_cache = message_cache
        self._context_guard = context_guard

    @property
    def agent_card(self) -> AgentCard:
        """Card the SDK uses for streaming and push capability checks."""
        return self._agent_card

    def set_agent_card(self, agent_card: AgentCard) -> None:
        """Replace the card after a model hot-swap.

        ``DefaultRequestHandler`` reads the private ``_agent_card`` when it
        decides whether streaming and push notifications are supported. This
        setter is the only write, so an SDK upgrade that renames the field
        fails here instead of leaving capability checks on the old card.
        """
        self._agent_card = agent_card

    @property
    def message_cache(self) -> A2AMessageCache:
        """Terminal-task cache and in-flight registry for ``messageId`` dedup."""
        return self._message_cache

    async def _setup_active_task(
        self,
        params: SendMessageRequest,
        call_context: ServerCallContext,
    ) -> tuple[ActiveTask, RequestContext]:
        """Scope the send/stream subscription to this request's own events.

        See :class:`_RequestScopedActiveTask`. Without a ``messageId`` there is
        no marker to wait for, so the SDK subscription is used unchanged.
        """
        active_task, request_context = await super()._setup_active_task(
            params, call_context
        )
        message_id = params.message.message_id
        if not message_id or params.message.role != Role.ROLE_USER:
            return active_task, request_context
        scoped = _RequestScopedActiveTask(active_task, message_id)
        return cast("ActiveTask", scoped), request_context

    async def prepare_message_dispatch(
        self,
        params: SendMessageRequest,
        context: ServerCallContext | None = None,
    ) -> tuple[Literal["cached", "proceed"], Task | None, CacheKey | None]:
        """Check cache and in-flight state before the SDK starts execution.

        Returns ``("cached", task, cache_key)`` on replay,
        ``("proceed", None, cache_key)`` when processing continues, or
        ``("proceed", None, None)`` when ids are missing.
        Raises :class:`~rasa.core.a2a_server.errors.A2AMessageInFlightConflict`
        if the same key is already in flight.

        On ``proceed`` with a key, the new in-flight lease is stashed on
        ``context`` so later task-store saves and setup errors act only on this
        request's registration, not on a retry that re-registered the key after
        this one expired.

        The key includes the authenticated caller, so one principal can neither
        replay nor block another principal's ``(context_id, message_id)``.
        """
        context = _call_context(context)
        context.state.pop(IN_FLIGHT_LEASE_STATE_KEY, None)
        cache_key = await self._resolve_cache_key(params, context)
        if cache_key is None:
            return "proceed", None, None

        cached = await self._message_cache.get(cache_key)
        if cached is not None:
            structlogger.debug(
                "a2a_server.rasa_a2a_request_handler.cache_hit",
                context_id=cache_key.context_id,
                message_id=cache_key.message_id,
            )
            return "cached", cached, cache_key

        lease = await self._message_cache.try_begin_in_flight(cache_key)
        if lease is None:
            raise A2AMessageInFlightConflict(
                context_id=cache_key.context_id, message_id=cache_key.message_id
            )
        context.state[IN_FLIGHT_LEASE_STATE_KEY] = lease
        return "proceed", None, cache_key

    async def on_cancel_task(
        self,
        params: CancelTaskRequest,
        context: ServerCallContext | None = None,
    ) -> Task | None:
        """Handle tasks/cancel and POST the terminal canceled task if needed.

        When the executor publishes a ``canceled`` event, the SDK consumer
        already pushes it. The SDK only writes ``canceled`` straight to the
        store, without a push, when no event reached it (for example the agent
        was not ready). The fallback POST below covers that case only; the
        ledger tells the two apart. A failed fallback POST is logged, not
        raised: the task is already canceled.
        """
        try:
            task = await super().on_cancel_task(params, _call_context(context))
        except A2APushNotificationUrlRejected as exc:
            _raise_push_url_policy_error(exc)
        if (
            task is None
            or not task.id
            or task.status.state != TaskState.TASK_STATE_CANCELED
            or self._push_ledger is None
            or self._push_ledger.has_terminal_push(task.id)
        ):
            return task
        try:
            await self._push_ledger.send_notification(task.id, task)
        except Exception as exc:
            structlogger.error(
                "a2a_server.rasa_a2a_request_handler.cancel_push_failed",
                task_id=task.id,
                error=str(exc),
                exc_info=exc,
            )
        return task

    def _reject_inline_push_when_disabled(self, params: SendMessageRequest) -> None:
        has_push_config = params.HasField(
            "configuration"
        ) and params.configuration.HasField("task_push_notification_config")
        if has_push_config and not self._push_config_store:
            raise PushNotificationNotSupportedError(
                message="Push notifications are disabled on this server."
            )

    async def _reject_mismatched_task_context(
        self,
        params: SendMessageRequest,
        context: ServerCallContext | None,
    ) -> None:
        """Reject a message whose ``context_id`` does not belong to ``task_id``.

        Spec 3.4.2 requires the server to infer ``context_id`` from the task
        when only ``task_id`` is set, and to reject a pair that disagrees.
        """
        message = params.message
        if not message.task_id or not message.context_id:
            return
        task = await self.task_store.get(message.task_id, _call_context(context))
        if task is None or not task.context_id:
            return
        if task.context_id != message.context_id:
            raise InvalidParamsError(
                message=(
                    f"context_id {message.context_id!r} does not match "
                    f"task {task.id!r} (context_id {task.context_id!r})"
                )
            )

    async def on_create_task_push_notification_config(
        self,
        params: Any,
        context: ServerCallContext | None = None,
    ) -> Any:
        try:
            return await super().on_create_task_push_notification_config(
                params, context
            )
        except A2APushNotificationUrlRejected as exc:
            _raise_push_url_policy_error(exc)

    async def on_message_send(
        self,
        params: SendMessageRequest,
        context: ServerCallContext | None = None,
    ) -> Message | Task:
        """Handle ``message/send`` with dedup and terminal-task recording."""
        context = _call_context(context)
        context.state[STREAMING_CALLER_STATE_KEY] = False
        self._reject_inline_push_when_disabled(params)
        validate_history_length(params.configuration)
        await self._reject_mismatched_task_context(params, context)

        mode, cached, _ = await self.prepare_message_dispatch(params, context)
        if mode == "cached" and cached is not None:
            return task_for_replay_from_params(cached, params)

        rejected = await self._reject_context_over_limit(params, context)
        if rejected is not None:
            return rejected

        try:
            return await super().on_message_send(params, context)
        except A2APushNotificationUrlRejected as exc:
            await self._end_in_flight_after_setup_error(context)
            _raise_push_url_policy_error(exc)
        except Exception:
            await self._end_in_flight_after_setup_error(context)
            raise

    async def build_message_send_stream(
        self,
        params: SendMessageRequest,
        context: ServerCallContext | None = None,
    ) -> AsyncGenerator[Event, None]:
        """Return the ``message/stream`` event generator after dedup.

        Await before SSE so cache hits and in-flight conflicts resolve first.
        """
        context = _call_context(context)
        context.state[STREAMING_CALLER_STATE_KEY] = True
        self._reject_inline_push_when_disabled(params)
        validate_history_length(params.configuration)
        await self._reject_mismatched_task_context(params, context)
        mode, cached, _ = await self.prepare_message_dispatch(params, context)
        if mode == "cached" and cached is not None:
            return replay_cached_stream(cached, params)
        rejected = await self._reject_context_over_limit(params, context)
        if rejected is not None:
            return _single_task_stream(rejected)
        return self._message_send_stream_live(params, context)

    async def on_message_send_stream(
        self,
        params: SendMessageRequest,
        context: ServerCallContext | None = None,
    ) -> AsyncGenerator[Event, None]:
        """SDK ``message/stream`` entry; delegates to ``build_message_send_stream``."""
        stream = await self.build_message_send_stream(params, context)
        async for event in stream:
            yield event

    async def _message_send_stream_live(
        self,
        params: SendMessageRequest,
        context: ServerCallContext,
    ) -> AsyncGenerator[Event, None]:
        """Run the SDK stream after in-flight has been registered.

        Recording and ``end_in_flight`` happen in the task store when V2
        persists a cacheable task, not when this generator returns.
        """
        try:
            async for event in super().on_message_send_stream(params, context):
                yield event
        except A2APushNotificationUrlRejected as exc:
            await self._end_in_flight_after_setup_error(context)
            _raise_push_url_policy_error(exc)
        except Exception:
            await self._end_in_flight_after_setup_error(context)
            raise

    async def _reject_context_over_limit(
        self, params: SendMessageRequest, context: ServerCallContext
    ) -> Task | None:
        """Persist and return a ``failed`` task when a new context is over the cap.

        Runs after dedup and before the SDK starts a producer, so a rejected
        send runs no turn and publishes no events. Only a send that opens a new
        task is rejected: a follow-up names a task whose context is already
        reserved. The check reserves nothing; the executor's reservation stays
        the authoritative one.

        The failure is plain text, so it is not cached: the cap is transient,
        and a retry of the same ``messageId`` must run once a slot frees. Each
        rejected attempt is its own task and stays ``failed``.
        """
        message = params.message
        guard = self._context_guard
        if (
            guard is None
            or message.task_id
            or not message.context_id
            or not await guard.would_exceed_limit(message.context_id)
        ):
            return None

        structlogger.warning(
            "a2a_server.rasa_a2a_request_handler.context_limit",
            context_id=message.context_id,
            active_context_count=guard.active_context_count,
            max_contexts=guard.max_contexts,
        )
        task = Task(id=str(uuid.uuid4()), context_id=message.context_id)
        task.history.add().CopyFrom(message)
        task.status.CopyFrom(
            TaskStatus(
                state=TaskState.TASK_STATE_FAILED,
                message=new_text_message(
                    CONTEXT_LIMIT_EXCEEDED_ERROR,
                    context_id=task.context_id,
                    task_id=task.id,
                ),
            )
        )
        task.status.timestamp.GetCurrentTime()
        try:
            await self.task_store.save(task, context)
        except Exception:
            await self._end_in_flight_after_setup_error(context)
            raise
        return apply_history_length(task, params.configuration)

    async def _resolve_cache_key(
        self,
        params: SendMessageRequest,
        context: ServerCallContext | None = None,
    ) -> CacheKey | None:
        """Return a caller-scoped dedup key and pin resolved ids on ``params``.

        Resolution uses a copy so the SDK can generate ids. Only ``context_id``
        (and a ``task_id`` taken from an existing stored task) are written back
        onto the live request. A generated ``task_id`` is not: V2 treats a set
        ``task_id`` as an existing task and raises ``TaskNotFoundError``.

        A message with neither ``context_id`` nor ``task_id`` starts a new
        conversation. Its ``context_id`` is derived from the caller and
        ``message_id`` rather than generated, so a retry that still omits it
        resolves to the same key.
        """
        message = params.message
        params_for_resolution = SendMessageRequest()
        params_for_resolution.CopyFrom(params)
        resolution_message = params_for_resolution.message
        call_context = _call_context(context)
        owner = caller_scope(call_context)
        task: Task | None = None
        if resolution_message.task_id:
            task = await self.task_store.get(resolution_message.task_id, call_context)

        request_context = await self._request_context_builder.build(
            context=call_context,
            params=params_for_resolution,
            task_id=task.id if task else resolution_message.task_id or None,
            context_id=resolution_message.context_id
            or (task.context_id if task else None)
            or _context_id_for_new_conversation(owner, resolution_message),
            task=task,
        )
        self._pin_resolved_ids_on_message(
            message,
            resolved_context_id=request_context.context_id,
            stored_task=task,
        )
        return cache_key_from_dispatch(
            message,
            owner=owner,
            context_id_fallback=request_context.context_id,
        )

    def _pin_resolved_ids_on_message(
        self,
        message: Message,
        *,
        resolved_context_id: str | None,
        stored_task: Task | None,
    ) -> None:
        """Copy omitted conversation ids from resolution onto ``message``."""
        if not message.context_id:
            context_id = resolved_context_id or (
                stored_task.context_id if stored_task is not None else None
            )
            if context_id:
                message.context_id = context_id
            elif message.message_id or stored_task is not None:
                # A stored Task can omit context_id (empty proto default).
                # Dedup needs both ids, so this send will not be cached.
                structlogger.warning(
                    "a2a_server.rasa_a2a_request_handler.context_id_unresolved",
                    message_id=message.message_id or None,
                    task_id=message.task_id or None,
                    stored_task_id=(
                        stored_task.id if stored_task is not None else None
                    ),
                    stored_task_missing_context_id=(
                        stored_task is not None and not stored_task.context_id
                    ),
                )
        if not message.task_id and stored_task is not None and stored_task.id:
            message.task_id = stored_task.id

    async def _end_in_flight_after_setup_error(
        self, context: ServerCallContext
    ) -> None:
        """End this request's in-flight lease when ``super()`` fails."""
        lease = in_flight_lease_from_call_context(context)
        if lease is not None:
            await self._message_cache.end_in_flight(lease)
